import {
  ToggleGroup as ToggleGroupPrimitive,
  useToggleGroup,
  useToggleGroupContext,
} from '@ark-ui/solid/toggle-group';
import { clsx } from 'clsx';
import type { Accessor, ComponentProps } from 'solid-js';
import { createContext, splitProps, useContext } from 'solid-js';
import type { ToggleSize, ToggleVariant } from '../toggle/Toggle';
import toggleStyles from '../toggle/Toggle.module.css';
import styles from './ToggleGroup.module.css';

const defaultToggleGroupStyles = {
  variant: () => 'default' as ToggleVariant,
  size: () => 'md' as ToggleSize,
};

type ToggleGroupStyleContextValue = {
  variant: Accessor<ToggleVariant>;
  size: Accessor<ToggleSize>;
};

const ToggleGroupStyleContext =
  createContext<ToggleGroupStyleContextValue>(defaultToggleGroupStyles);

type ToggleGroupRootProps = ComponentProps<typeof ToggleGroupPrimitive.Root> & {
  variant?: ToggleVariant;
  size?: ToggleSize;
};

type ToggleGroupRootProviderProps = ComponentProps<typeof ToggleGroupPrimitive.RootProvider> & {
  variant?: ToggleVariant;
  size?: ToggleSize;
};

type ToggleGroupItemProps = ComponentProps<typeof ToggleGroupPrimitive.Item> & {
  variant?: ToggleVariant;
  size?: ToggleSize;
};

function ToggleGroup(props: ToggleGroupRootProps) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class', 'size', 'variant']);
  const variant = () => local.variant ?? 'default';
  const size = () => local.size ?? 'md';

  return (
    <ToggleGroupStyleContext.Provider value={{ variant, size }}>
      <ToggleGroupPrimitive.Root
        asChild={local.asChild}
        {...others}
        data-slot="toggle-group-root"
        data-variant={variant()}
        data-size={size()}
        class={clsx(styles.root, local.class)}
      >
        {local.children}
      </ToggleGroupPrimitive.Root>
    </ToggleGroupStyleContext.Provider>
  );
}

function ToggleGroupRootProvider(props: ToggleGroupRootProviderProps) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class', 'size', 'variant']);
  const variant = () => local.variant ?? 'default';
  const size = () => local.size ?? 'md';

  return (
    <ToggleGroupStyleContext.Provider value={{ variant, size }}>
      <ToggleGroupPrimitive.RootProvider
        asChild={local.asChild}
        {...others}
        data-slot="toggle-group-root-provider"
        data-variant={variant()}
        data-size={size()}
        class={clsx(styles.root, local.class)}
      >
        {local.children}
      </ToggleGroupPrimitive.RootProvider>
    </ToggleGroupStyleContext.Provider>
  );
}

function ToggleGroupItem(props: ToggleGroupItemProps) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class', 'size', 'variant']);
  const inherited = useContext(ToggleGroupStyleContext);
  const variant = () => local.variant ?? inherited.variant();
  const size = () => local.size ?? inherited.size();

  return (
    <ToggleGroupPrimitive.Item
      asChild={local.asChild}
      {...others}
      data-slot="toggle-group-item"
      data-variant={variant()}
      data-size={size()}
      class={clsx(toggleStyles.root, styles.item, local.class)}
    >
      {local.children}
    </ToggleGroupPrimitive.Item>
  );
}

const ToggleGroupContext = ToggleGroupPrimitive.Context;

export {
  ToggleGroup,
  ToggleGroupContext,
  ToggleGroupItem,
  ToggleGroupRootProvider,
  useToggleGroup,
  useToggleGroupContext,
};
export type {
  ToggleGroupItemProps,
  ToggleGroupRootProps,
  ToggleGroupRootProviderProps,
  ToggleSize,
  ToggleVariant,
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    max-inline-size: 100%;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
    --moduix-toggle-color: var(--moduix-toggle-group-color, var(--moduix-color-foreground));
    gap: var(--moduix-toggle-group-gap, var(--moduix-border-width-sm));
    padding: var(--moduix-toggle-group-padding, var(--moduix-border-width-md));
    border: var(--moduix-toggle-group-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-toggle-group-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-toggle-group-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-toggle-group-bg, var(--moduix-color-muted));
    color: var(--moduix-toggle-group-color, var(--moduix-color-foreground));

    &::-webkit-scrollbar {
      display: none;
    }

    &[data-orientation='vertical'] {
      flex-direction: column;
      align-items: stretch;

      & > .item {
        width: 100%;
        justify-content: flex-start;
      }
    }

    &[data-variant='ghost'] {
      padding: var(--moduix-toggle-group-padding, var(--moduix-toggle-group-ghost-padding, 0));
      border-color: var(
        --moduix-toggle-group-border-color,
        var(--moduix-toggle-group-ghost-border-color, transparent)
      );
      background-color: var(
        --moduix-toggle-group-bg,
        var(--moduix-toggle-group-ghost-bg, transparent)
      );
    }

    &[data-variant='outline'] {
      background-color: var(
        --moduix-toggle-group-bg,
        var(--moduix-toggle-group-outline-bg, var(--moduix-color-background))
      );
    }
  }

  .item {
    flex: 0 0 auto;
    border-radius: var(--moduix-toggle-group-item-radius, var(--moduix-radius-md));
  }
}

export {
  ToggleGroup,
  ToggleGroupContext,
  ToggleGroupItem,
  ToggleGroupRootProvider,
  useToggleGroup,
  useToggleGroupContext,
} from './ToggleGroup.js';
export type {
  ToggleGroupItemProps,
  ToggleGroupRootProps,
  ToggleGroupRootProviderProps,
  ToggleSize,
  ToggleVariant,
} from './ToggleGroup.js';
